/**
 * A DICOM *writer*, so that the reader can be tested against something that was
 * not derived from it.
 *
 * The reader under test was written from PS3.5 and PS3.10. This was written
 * from the same documents and from neither the reader nor any other
 * implementation, which is the whole value of it: a fixture generated by the
 * code under test would agree with that code about a shared mistake, and these
 * two can only agree by both being right about the format.
 *
 * It writes all four of the encodings a dataset can be in - implicit and
 * explicit VR, little and big endian - because the four are not variations on
 * one parser path, they are four parser paths, and the one that is never
 * exercised is the one that is wrong.
 */

/** Join byte runs, exactly as tests/js/helpers.js does for the image parsers. */
export const concat = (...parts) => {
  const runs = parts.map((part) => (part instanceof Uint8Array
    ? part : Array.isArray(part) ? Uint8Array.from(part) : part));
  const out = new Uint8Array(runs.reduce((total, run) => total + run.length, 0));
  let at = 0;
  for (const run of runs) {
    out.set(run, at);
    at += run.length;
  }
  return out;
};

export const ascii = (value) => {
  const out = new Uint8Array(value.length);
  for (let at = 0; at < value.length; at += 1) out[at] = value.charCodeAt(at) & 0xff;
  return out;
};

const u16 = (value, little = true) => (little
  ? [value & 0xff, (value >> 8) & 0xff]
  : [(value >> 8) & 0xff, value & 0xff]);

const u32 = (value, little = true) => (little
  ? [value & 0xff, (value >> 8) & 0xff, (value >> 16) & 0xff, (value >>> 24) & 0xff]
  : [(value >>> 24) & 0xff, (value >> 16) & 0xff, (value >> 8) & 0xff, value & 0xff]);

/** The VRs whose length field is 32 bits, after two reserved bytes. */
const LONG_FORM = new Set(['OB', 'OD', 'OF', 'OL', 'OV', 'OW', 'SQ', 'UC', 'UN', 'UR', 'UT']);

/**
 * Pad to an even length, which every DICOM value must be.
 *
 * The pad byte is a space for text and a null for UI and for binary, and the
 * distinction is not decorative: a reader that strips only spaces leaves a null
 * on the end of every UID, and a UID with a null on it compares equal to
 * nothing.
 */
function pad(bytes, vr) {
  if (bytes.length % 2 === 0) return bytes;
  const filler = vr === 'UI' || vr === 'OB' || vr === 'UN' ? 0 : 0x20;
  return concat(bytes, [filler]);
}

/**
 * One element.
 *
 * @param {string} tag    eight hex digits
 * @param {string} vr
 * @param {Uint8Array|number[]|string} value
 * @param {{explicit?: boolean, little?: boolean}} syntax
 */
export function element(tag, vr, value, { explicit = true, little = true } = {}) {
  const group = parseInt(tag.slice(0, 4), 16);
  const number = parseInt(tag.slice(4), 16);

  const raw = typeof value === 'string' ? ascii(value)
    : value instanceof Uint8Array ? value : Uint8Array.from(value);
  const bytes = pad(raw, vr);

  const head = concat(u16(group, little), u16(number, little));

  if (!explicit) return concat(head, u32(bytes.length, little), bytes);
  if (LONG_FORM.has(vr)) {
    return concat(head, ascii(vr), [0, 0], u32(bytes.length, little), bytes);
  }
  return concat(head, ascii(vr), u16(bytes.length, little), bytes);
}

/** A US or SS value, as the two bytes the file holds. */
export const short = (value, little = true) => Uint8Array.from(u16(value & 0xffff, little));

/** A run of 16-bit samples, in the file's byte order. */
export function words(values, little = true) {
  const out = new Uint8Array(values.length * 2);
  for (let at = 0; at < values.length; at += 1) {
    const pair = u16(values[at] & 0xffff, little);
    out[at * 2] = pair[0];
    out[at * 2 + 1] = pair[1];
  }
  return out;
}

/** A sequence item, either with a length or delimited. */
export function item(content, { delimited = false, little = true } = {}) {
  if (!delimited) return concat(u16(0xfffe, little), u16(0xe000, little), u32(content.length), content);
  return concat(
    u16(0xfffe, little), u16(0xe000, little), u32(0xffffffff),
    content,
    u16(0xfffe, little), u16(0xe00d, little), u32(0),
  );
}

export const sequenceEnd = (little = true) => concat(
  u16(0xfffe, little), u16(0xe0dd, little), u32(0),
);

/** An encapsulated Pixel Data element: an offset table, then one item a frame. */
export function encapsulated(fragments, table = [], { little = true } = {}) {
  const offsets = new Uint8Array(table.length * 4);
  for (let at = 0; at < table.length; at += 1) offsets.set(u32(table[at]), at * 4);

  return concat(
    u16(0x7fe0, little), u16(0x0010, little), ascii('OB'), [0, 0], u32(0xffffffff),
    item(offsets, { little }),
    ...fragments.map((fragment) => item(pad(fragment, 'OB'), { little })),
    sequenceEnd(little),
  );
}

/**
 * A whole PS3.10 file: preamble, magic, meta group, dataset.
 *
 * The meta group's own length is computed rather than passed in, because that
 * is the field a hand-written fixture gets wrong and the one the reader trusts
 * to find where the dataset begins.
 */
export function file(transferSyntax, dataset, { sopClass = '1.2.840.10008.5.1.4.1.1.7' } = {}) {
  const metaSyntax = { explicit: true, little: true };
  const meta = concat(
    element('00020001', 'OB', [0, 1], metaSyntax),
    element('00020002', 'UI', sopClass, metaSyntax),
    element('00020003', 'UI', '1.2.3.4.5.6.7.8', metaSyntax),
    element('00020010', 'UI', transferSyntax, metaSyntax),
    element('00020012', 'UI', '1.2.826.0.1.3680043.9.7', metaSyntax),
  );

  return concat(
    new Uint8Array(128),
    ascii('DICM'),
    element('00020000', 'UL', Uint8Array.from(u32(meta.length)), metaSyntax),
    meta,
    dataset,
  );
}

/**
 * The image module every pixel test needs, as one block of elements.
 *
 * Written as a helper because eleven elements have to agree with each other for
 * a frame to be readable at all, and eleven separate `element` calls at the top
 * of every test is eleven chances for one of them to disagree with the pixels
 * underneath it.
 */
export function imageModule({
  rows, columns, bitsAllocated = 16, bitsStored = bitsAllocated, highBit = bitsStored - 1,
  signed = 0, samples = 1, photometric = 'MONOCHROME2', planar = null, frames = null,
  slope = null, intercept = null, center = null, width = null, spacing = null,
  syntax = {},
}) {
  const parts = [
    element('00280002', 'US', short(samples, syntax.little ?? true), syntax),
    element('00280004', 'CS', photometric, syntax),
    element('00280010', 'US', short(rows, syntax.little ?? true), syntax),
    element('00280011', 'US', short(columns, syntax.little ?? true), syntax),
    element('00280100', 'US', short(bitsAllocated, syntax.little ?? true), syntax),
    element('00280101', 'US', short(bitsStored, syntax.little ?? true), syntax),
    element('00280102', 'US', short(highBit, syntax.little ?? true), syntax),
    element('00280103', 'US', short(signed, syntax.little ?? true), syntax),
  ];

  if (planar !== null) parts.push(element('00280006', 'US', short(planar, syntax.little ?? true), syntax));
  if (frames !== null) parts.push(element('00280008', 'IS', String(frames), syntax));
  if (spacing !== null) parts.push(element('00280030', 'DS', spacing, syntax));
  if (center !== null) parts.push(element('00281050', 'DS', String(center), syntax));
  if (width !== null) parts.push(element('00281051', 'DS', String(width), syntax));
  if (intercept !== null) parts.push(element('00281052', 'DS', String(intercept), syntax));
  if (slope !== null) parts.push(element('00281053', 'DS', String(slope), syntax));

  // Elements must be in ascending tag order, and the four above are out of it
  // by construction. Sorting here rather than asking every caller to interleave
  // them correctly keeps the fixtures readable, and a reader that only worked
  // on sorted files would be a reader with a bug this hides - which is why
  // dicom-parse.test.js has a fixture that is deliberately out of order.
  return concat(...parts.sort(compareTags));
}

function compareTags(a, b) {
  const key = (bytes) => (bytes[1] << 24) | (bytes[0] << 16) | (bytes[3] << 8) | bytes[2];
  return key(a) - key(b);
}

/**
 * A ramp: every pixel a different value, counting up and wrapping.
 *
 * The fixture that catches a row-order mistake, an off-by-one in the unpacking
 * and a byte-order swap all at once, none of which a flat fill would show.
 */
export function ramp(count, modulo = 4096, from = 0) {
  const out = new Int32Array(count);
  for (let at = 0; at < count; at += 1) out[at] = from + (at % modulo);
  return out;
}

/* ------------------------------------------------------------ RLE Lossless */

/**
 * The RLE encoder, written from PS3.5 annex G.
 *
 * Takes a frame exactly as an uncompressed Pixel Data element would hold it -
 * samples interleaved, each in the file's little-endian order - and splits it
 * into the byte planes the format codes. Segment 0 is the most significant byte
 * of sample 0, which is the part of annex G that readers get wrong and that
 * produces a picture that is recognisable and numerically wrong.
 */
export function encodeRLE(frame, pixels, samples, bytesPerSample) {
  const segments = [];

  for (let sample = 0; sample < samples; sample += 1) {
    for (let byte = 0; byte < bytesPerSample; byte += 1) {
      const plane = new Uint8Array(pixels);
      for (let at = 0; at < pixels; at += 1) {
        // The byte at `byte` counting down from the most significant, which in
        // a little-endian frame is the last byte of the sample.
        plane[at] = frame[at * samples * bytesPerSample
          + sample * bytesPerSample + (bytesPerSample - 1 - byte)];
      }
      segments.push(packBits(plane));
    }
  }

  const header = new Uint8Array(64);
  const view = new DataView(header.buffer);
  view.setUint32(0, segments.length, true);

  let offset = 64;
  for (let at = 0; at < segments.length; at += 1) {
    view.setUint32(4 + at * 4, offset, true);
    offset += segments[at].length;
  }

  return concat(header, ...segments);
}

/** PackBits: replicate runs where they pay, literals otherwise. */
function packBits(bytes) {
  const out = [];
  let at = 0;

  while (at < bytes.length) {
    let run = 1;
    while (at + run < bytes.length && bytes[at + run] === bytes[at] && run < 128) run += 1;

    if (run >= 3) {
      out.push(257 - run, bytes[at]);
      at += run;
      continue;
    }

    // A literal run, ended by the first repeat long enough to be worth coding.
    const from = at;
    let length = 0;
    while (at < bytes.length && length < 128) {
      const repeats = at + 2 < bytes.length
        && bytes[at] === bytes[at + 1] && bytes[at] === bytes[at + 2];
      if (repeats) break;
      at += 1;
      length += 1;
    }
    out.push(length - 1);
    for (let step = 0; step < length; step += 1) out.push(bytes[from + step]);
  }

  if (out.length % 2 === 1) out.push(0);
  return Uint8Array.from(out);
}

/* --------------------------------------------------------- JPEG lossless */

/**
 * A JPEG lossless encoder, to the extent one scan of predictor 1 needs.
 *
 * The same argument as the DICOM writer above: `jpeg-lossless.js` was written
 * from ITU T.81 annex H, and so was this, and a round trip through the two only
 * succeeds if both read the same specification the same way.
 *
 * The Huffman table is fixed and trivially unbalanced - the code for category
 * `n` is `n` ones followed by a zero - so that the encoder needs no frequency
 * pass and the decoder still has to walk the canonical code lengths properly to
 * read it. A table where every code were the same length would let a broken
 * decoder pass.
 */
export function encodeJPEGLossless(samples, width, height, precision, components = 1) {
  const counts = new Uint8Array(16);
  const symbols = [];
  // One symbol at each code length from 1 to 16: category 0 is a single zero
  // bit, category 1 is `10`, category 2 is `110`, and so on.
  for (let length = 1; length <= 16; length += 1) {
    counts[length - 1] = 1;
    symbols.push(length - 1);
  }

  const bits = new BitWriter();
  const previous = new Int32Array(width * components);
  const start = 1 << (precision - 1);

  for (let row = 0; row < height; row += 1) {
    for (let column = 0; column < width; column += 1) {
      for (let component = 0; component < components; component += 1) {
        const at = (row * width + column) * components + component;
        const value = samples[at] & ((1 << precision) - 1);

        const predicted = row === 0 && column === 0 ? start
          : column === 0 ? previous[component]
            : samples[at - components] & ((1 << precision) - 1);

        const diff = value - predicted;
        const category = magnitude(diff);
        writeSymbol(bits, counts, symbols, category);
        if (category > 0 && category < 16) {
          bits.write(diff > 0 ? diff : diff + (1 << category) - 1, category);
        }
        if (column === 0) previous[component] = value;
      }
    }
  }

  const scanData = bits.finish();

  const frameHeader = [precision, height >> 8, height & 0xff, width >> 8, width & 0xff, components];
  for (let component = 0; component < components; component += 1) {
    frameHeader.push(component + 1, 0x11, 0);
  }

  const huffman = [0x00, ...counts, ...symbols];

  const scanHeader = [components];
  for (let component = 0; component < components; component += 1) {
    scanHeader.push(component + 1, 0x00);
  }
  scanHeader.push(1, 0, 0);   // predictor 1, Se = 0, no point transform

  return concat(
    [0xff, 0xd8],
    [0xff, 0xc3], u16(frameHeader.length + 2, false), frameHeader,
    [0xff, 0xc4], u16(huffman.length + 2, false), huffman,
    [0xff, 0xda], u16(scanHeader.length + 2, false), scanHeader,
    scanData,
    [0xff, 0xd9],
  );
}

/** How many bits a difference needs, which is the Huffman symbol. */
function magnitude(diff) {
  const size = Math.abs(diff);
  let category = 0;
  while (size >= (1 << category)) category += 1;
  return category;
}

function writeSymbol(bits, counts, symbols, symbol) {
  let code = 0;
  let index = 0;
  for (let length = 1; length <= 16; length += 1) {
    for (let step = 0; step < counts[length - 1]; step += 1) {
      if (symbols[index] === symbol) {
        bits.write(code, length);
        return;
      }
      index += 1;
      code += 1;
    }
    code <<= 1;
  }
  throw new Error(`no Huffman code for category ${symbol}`);
}

/** Bits, most significant first, with the 0xFF stuffing the format requires. */
class BitWriter {
  constructor() {
    this.bytes = [];
    this.buffer = 0;
    this.count = 0;
  }

  write(value, length) {
    for (let at = length - 1; at >= 0; at -= 1) {
      this.buffer = (this.buffer << 1) | ((value >> at) & 1);
      this.count += 1;
      if (this.count === 8) this.flush();
    }
  }

  flush() {
    this.bytes.push(this.buffer & 0xff);
    // A 0xFF in the entropy-coded data is followed by a 0x00 so that it cannot
    // be read as a marker.
    if ((this.buffer & 0xff) === 0xff) this.bytes.push(0);
    this.buffer = 0;
    this.count = 0;
  }

  finish() {
    // The last byte is padded with ones, which is what the format specifies and
    // is not arbitrary: a run of ones cannot be the start of a valid code in
    // the table above, so a decoder cannot read the padding as another sample.
    while (this.count !== 0) this.write(1, 1);
    return Uint8Array.from(this.bytes);
  }
}
